from pydantic import BaseModel, ValidationError, ValidatorFunctionWrapHandler, field_validator


class Tags(BaseModel):
    tags: list[str]
    score: int

    @field_validator("tags", mode="before")
    @classmethod
    def split_csv(cls, v: Any) -&gt; Any:
        if isinstance(v, str):
            return [t.strip() for t in v.split(",") if t.strip()]
        return v

    @field_validator("score", mode="wrap")
    @classmethod
    def default_on_failure(cls, v: Any, handler: ValidatorFunctionWrapHandler) -&gt; int:
        try:
            return handler(v)
        except ValidationError:
            return 0


print(Tags(tags="ai, python , pydantic", score="oops"))
# tags=['ai', 'python', 'pydantic'] score=0
